import subprocess, time, urllib.request, urllib.error, socket, os

def free_port():
    import socket
    s=socket.socket(); s.bind(('127.0.0.1',0)); p=s.getsockname()[1]; s.close(); return p

def test_once(args, path="/", method="GET", headers={}, data=None, query=""):
    port=free_port()
    proc=subprocess.Popen(["./executable","-p",str(port)]+args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    time.sleep(0.8)
    if proc.poll() is not None:
        out,err=proc.communicate()
        print("failed start",out,err)
        return
    import http.client
    conn=http.client.HTTPConnection("127.0.0.1",port,timeout=5)
    try:
        conn.request(method, path, body=data, headers=headers)
        resp=conn.getresponse()
        print(f"== {method} {path} => {resp.status} {resp.reason}")
