            except: print(body[:1000])
        else:
            print(body[:2000].decode(errors='replace')[:2000])
    except Exception as e:
        print("err",e)
    finally:
        conn.close()
        proc.terminate()
        try: out,err=proc.communicate(timeout=3)
        except: proc.kill()
        #print(out,err)

# Test file serving
test_once(["/tmp/testroot"], path="/file1.txt")
