def _is_help_request(argv):
    # check before -- separator
    end = len(argv)
    if "--" in argv:
        end = argv.index("--")
    has_long_help = False
    has_short_help = False
    has_version = False
    for tok in argv[:end]:
        if tok == "--help":
            has_long_help = True
        elif tok == "--version":
            has_version = True
        elif tok.startswith("-") and not tok.startswith("--") and len(tok)>1:
            # short cluster
            if "h" in tok[1:]:
                has_short_help = True
            if "V" in tok[1:]:
                has_version = True
        elif tok == "-h":
            has_short_help = True
        elif tok == "-V":
            has_version = True
    # long help takes precedence over short? If both, long?
    if has_long_help:
        return "long"
    if has_short_help:
        return "short"
    if has_version:
        return "version"
    return None

