# ===== Helpers for serving =====
def human_size(n):
    if n < 1024:
        return f"{n} B"
    elif n < 1024*1024:
        v = n/1024
        return f"{v:.1f} KiB"
    elif n < 1024*1024*1024:
        v = n/(1024*1024)
        return f"{v:.1f} MiB"
    elif n < 1024*1024*1024*1024:
        v = n/(1024*1024*1024)
        return f"{v:.1f} GiB"
    else:
        v = n/(1024*1024*1024*1024)
        return f"{v:.1f} TiB"

def exact_size(n):
    return f"{n} B"

def format_mtime_abs(ts):
    dt = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc)
    return dt.strftime("%Y-%m-%d %H:%M:%S +00:00")

def format_relative(ts, now=None):
    if now is None:
        now = time.time()
    delta = int(now - ts)
    if delta < 0:
        delta = 0
    if delta < 10:
        return "now"
    if delta < 60:
        return f"{delta} seconds ago"
    mins = delta // 60
    # Use rounding? For 90s, delta=90, mins=1, but original shows "2 minutes ago" for 90s. So need rounding, not floor.
    # Let's use round(delta/60)
    mins_r = round(delta/60)
    if delta < 3600:
        if mins_r <= 1:
            # Check: for 60-89s, round=1 -> "a minute ago"? For 90s, round=2 -> "2 minutes ago"
            # Need to distinguish: if mins_r==1: "a minute ago" else f"{mins_r} minutes ago"
            # But what about 30s? Already handled as seconds. So for 60s+, use this.
            return "a minute ago" if mins_r == 1 else f"{mins_r} minutes ago"
        else:
            return f"{mins_r} minutes ago"
    hours_r = round(delta/3600)
    if delta < 86400:
        if hours_r <= 1:
            return "an hour ago"
        else:
