def make_href(rp, url_path, name, is_dir, is_raw=False, ext_url=None):
    # url_path like "/" or "/subdir/"
    # name is file/dir name (without slash)
    # For file-external-url, file links use ext_url + relative path, dirs still use rp? Original: with ext_url, file links use external, dir links still internal? Let's check: earlier with ext_url, file links were external, but what about dir links? We didn't check. Assume dirs still internal (since browsing via internal, files via external). We'll do that.
