    v = config.get("upload-files")
    if v is None:
        return False
    if v is True:
        return True
    # v is string like "/upload" (relative to serve dir, with leading slash? Could be "upload" or "/upload"?)
    # Normalize: ensure leading slash, no trailing?
    allowed = str(v)
    if not allowed.startswith("/"):
        allowed = "/" + allowed
    allowed = allowed.rstrip("/") or "/"
    # url_path like "/" or "/subdir/" -> normalize similarly
    cur = url_path.rstrip("/") or "/"
    # If allowed is "/", then all allowed? Actually if allowed is "/upload", then only /upload and subdirs allowed, not root.
    # Check if cur == allowed or cur startswith allowed + "/"
    if cur == allowed or cur.startswith(allowed + "/"):
        return True
    return False

