def decode_chunked(data):
    # data is chunked encoding bytes, decode to raw
    out = b""
    i = 0
    while i < len(data):
        # find CRLF
        j = data.find(b"\r\n", i)
        if j == -1:
            break
        line = data[i:j].decode("iso-8859-1").strip()
        # line may contain extensions after ;
        if ";" in line:
            line = line.split(";")[0]
        try:
            size = int(line, 16)
        except:
            break
        i = j + 2
        if size == 0:
            break
        out += data[i:i+size]
        i += size + 2  # skip CRLF
    return out

