    segments = body.split(delim)
    # First segment is preamble (empty), last is epilogue (-- + \r\n)
    for seg in segments[1:]:
        # seg starts with \r\n or --?
        if seg.startswith(b"--"):
            # end
            break
        # Strip leading \r\n
        if seg.startswith(b"\r\n"):
            seg = seg[2:]
        # Find header end
        idx = seg.find(b"\r\n\r\n")
        if idx == -1:
            continue
        header_blob = seg[:idx].decode("iso-8859-1")
        data = seg[idx+4:]
        # Remove trailing \r\n (before next delim)
        if data.endswith(b"\r\n"):
            data = data[:-2]
        # Parse headers
        header_lines = header_blob.split("\r\n")
        disp = ""
        ctype = "text/plain"
        for hl in header_lines:
            if hl.lower().startswith("content-disposition:"):
