    except Exception as e:
        rp = ROUTE_PREFIX
        html = build_error_html(404, "Not Found", f"Route {url_path} could not be found", rp)
        b = html.encode()
        return (404, {"content-length":str(len(b)), "content-type":"text/html"}, b)
